import json, os, urllib.parse, urllib.request, ssl

def load_env(path):
    data = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#') or '=' not in line:
                continue
            k, v = line.split('=', 1)
            data[k] = v
    return data

def call(name, url, secret):
    req = urllib.request.Request(url, method='GET')
    req.add_header('Accept', 'application/json')
    req.add_header('Content-Type', 'application/json')
    req.add_header('x-client-id', 'health-passport')
    req.add_header('x-client-secret', secret)
    req.add_header('Accept-Language', 'en')
    try:
        with urllib.request.urlopen(req, timeout=25) as resp:
            body = resp.read().decode('utf-8', errors='replace')
            status = resp.status
    except urllib.error.HTTPError as e:
        body = e.read().decode('utf-8', errors='replace')
        status = e.code
    except Exception as e:
        print(json.dumps({'name': name, 'url_path': urllib.parse.urlparse(url).path, 'error': type(e).__name__, 'message': str(e)[:300]}, ensure_ascii=False))
        return
    parsed = None
    try:
        parsed = json.loads(body)
    except Exception:
        parsed = None
    summary = {'name': name, 'status': status, 'bytes': len(body)}
    if isinstance(parsed, dict):
        summary['top_keys'] = list(parsed.keys())[:12]
        summary['success'] = parsed.get('success')
        summary['status_field'] = parsed.get('status')
        data = parsed.get('data')
        if isinstance(data, dict):
            summary['data_keys'] = list(data.keys())[:12]
            if 'country' in data:
                summary['data_country'] = data.get('country')
            if 'countryCode' in data:
                summary['data_countryCode'] = data.get('countryCode')
        results = parsed.get('results')
        if isinstance(results, list) and results:
            comp = (results[0] or {}).get('address_components') or []
            if comp:
                summary['first_long_name'] = comp[0].get('long_name')
                summary['first_short_name'] = comp[0].get('short_name')
                summary['first_types'] = comp[0].get('types')
            summary['results_count'] = len(results)
        if parsed.get('message'):
            summary['message'] = str(parsed.get('message'))[:200]
        if parsed.get('error'):
            summary['error'] = str(parsed.get('error'))[:200]
        if parsed.get('localize_key'):
            summary['localize_key'] = parsed.get('localize_key')
    else:
        summary['body_prefix'] = body[:240]
    print(json.dumps(summary, ensure_ascii=False))

