import json, pathlib, subprocess
root=pathlib.Path('/Users/stark/Desktop/work/RN/heals-app-rn')
def env(path):
    d={}
    for line in path.read_text().splitlines():
        if line and not line.startswith('#') and '=' in line:
            k,v=line.split('=',1)
            d[k]=v
    return d
dev=env(root/'.env.development')

def call(name, url, secret):
    proc=subprocess.run([
        'curl','-sS','--noproxy','*','--max-time','25','-w','\n__HTTP__%{http_code}',
        '-H','Accept: application/json',
        '-H','x-client-id: health-passport',
        '-H', f'x-client-secret: {secret}',
        '-H','Accept-Language: en',
        url
    ], capture_output=True, text=True)
    text=proc.stdout
    if '__HTTP__' in text:
        body, code = text.rsplit('\n__HTTP__',1)
    else:
        body, code = text, 'unknown'
    summary={'name':name,'http':code.strip(),'curl_err':proc.stderr[-200:]}
    try:
        data=json.loads(body)
    except Exception:
        summary['body_prefix']=body[:180]
        print(json.dumps(summary, ensure_ascii=False))
        return
    if isinstance(data, dict):
        summary['top_keys']=list(data.keys())[:12]
        summary['success']=data.get('success')
        summary['status']=data.get('status')
        if data.get('message'):
            summary['message']=str(data.get('message'))[:180]
        data_obj=data.get('data')
        if isinstance(data_obj, dict):
            keep={k:data_obj.get(k) for k in data_obj if k.lower() in ('country','countrycode','country_code','region','city','ip','code','name') or 'country' in k.lower() or 'region' in k.lower()}
            summary['data_location_fields']=keep
            summary['data_keys']=list(data_obj.keys())[:20]
        results=data.get('results')
        if isinstance(results, list):
            summary['results_count']=len(results)
            if results:
                comps=results[0].get('address_components') or []
                if comps:
                    summary['first_component']={k:comps[0].get(k) for k in ('long_name','short_name','types')}
    print(json.dumps(summary, ensure_ascii=False))

